let __navHtml = null;
try { __navHtml = $('Nav laden (historische-marktdaten-WebhookGETAnsicht)').first().json.navHtml || $('Nav laden (historische-marktdaten-WebhookPOSTAenderung)').first().json.navHtml || null; } catch (e) { __navHtml = null; }

function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Berlin',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(date);
}

function esc(s) {
  return String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function fmtDate(v) {
  if (!v) return '-';
  const d = new Date(v);
  if (isNaN(d.getTime())) return '-';
  return d.toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
}
function fmtDateOnly(v) {
  if (!v) return '-';
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v).slice(0, 10);
  return d.toISOString().slice(0, 10);
}

// alwaysOutputData:true auf den DB-Nodes liefert bei 0 echten Treffern ein Platzhalter-Item
// (sonst wuerde n8n die nachfolgenden Nodes bei 0 Zeilen gar nicht erst ausfuehren) - anhand
// des jeweiligen Pflichtfelds herausfiltern, bevor weiterverarbeitet wird.
const watchlistTicker = $('DB: Watchlist fuer Formular laden').all().map(i => i.json).filter(j => j && j.ticker).map(j => j.ticker);
const jobs = $('DB: Jobs laden').all().map(i => i.json).filter(j => j && j.job_id);
const progressRows = $('DB: Job-Item-Fortschritt laden').all().map(i => i.json).filter(j => j && j.job_id);

const progressByJob = {};
for (const r of progressRows) {
  if (!progressByJob[r.job_id]) progressByJob[r.job_id] = {};
  progressByJob[r.job_id][r.status] = Number(r.anzahl);
}

const STATUS_LABEL = {
  draft: 'Entwurf', queued: 'wartet', running: 'laeuft', pausing: 'pausiert (wird beendet)',
  paused: 'pausiert', completed: 'abgeschlossen', completed_with_warnings: 'abgeschlossen (mit Warnungen)',
  failed: 'fehlgeschlagen', cancelled: 'abgebrochen'
};

const jobsHtml = jobs.map(j => {
  let jParams = {};
  try { jParams = typeof j.parameters_json === 'string' ? JSON.parse(j.parameters_json || '{}') : (j.parameters_json || {}); } catch (e) {}
  const zeitraum = (j.period_from && j.period_to) ? (esc(fmtDateOnly(j.period_from)) + ' - ' + esc(fmtDateOnly(j.period_to))) : esc(jParams.period || '-');
  const prog = progressByJob[j.job_id] || {};
  const done = (prog.completed || 0);
  const failed = (prog.failed || 0);
  const skipped = (prog.skipped || 0);
  const total = j.progress_total || 0;
  const pct = total > 0 ? Math.round(100 * (done + failed + skipped) / total) : 0;
  const statusLabel = STATUS_LABEL[j.status] || esc(j.status);
  const canPause = ['queued', 'running'].includes(j.status);
  const canResume = j.status === 'paused';
  const canCancel = ['draft', 'queued', 'running', 'pausing', 'paused'].includes(j.status);
  const canRetry = failed > 0 && ['completed_with_warnings', 'failed'].includes(j.status);

  let instruments = [];
  try { instruments = typeof j.instrument_selection_json === 'string' ? JSON.parse(j.instrument_selection_json || '[]') : (j.instrument_selection_json || []); } catch (e) {}

  function actionForm(action, label) {
    return '<form method="post" action="/webhook/historische-marktdaten" style="display:inline;">' +
      '<input type="hidden" name="action" value="' + action + '">' +
      '<input type="hidden" name="job_id" value="' + esc(j.job_id) + '">' +
      '<button type="submit">' + label + '</button></form>';
  }

  return '<tr>' +
    '<td>' + esc(j.job_id) + '</td>' +
    '<td>' + esc(j.provider) + '</td>' +
    '<td>' + instruments.length + ' Instrument(e)</td>' +
    '<td>' + zeitraum + '</td>' +
    '<td><span class="badge">' + statusLabel + '</span></td>' +
    '<td>' + done + '/' + total + ' (' + pct + '%)' + (failed ? ', ' + failed + ' fehlgeschlagen' : '') + '</td>' +
    '<td>' + fmtDate(j.heartbeat_at) + '</td>' +
    '<td>' +
      (canPause ? actionForm('pause', 'Pausieren') : '') +
      (canResume ? actionForm('resume', 'Fortsetzen') : '') +
      (canCancel ? actionForm('cancel', 'Abbrechen') : '') +
      (canRetry ? actionForm('retry_failed', 'Fehlgeschlagene wiederholen') : '') +
    '</td>' +
  '</tr>';
}).join('');

const prefillInstruments = watchlistTicker.join(', ');

const html = '<!DOCTYPE html><html lang="de"><head><meta charset="utf-8">' +
  '<title>Historische Marktdaten importieren</title>' +
  '<style>' +
  'body{font-family:sans-serif;background:#1a1a1a;color:#e0e0e0;padding:24px;}' +
  'h1{color:#fff;} table{border-collapse:collapse;width:100%;margin-top:12px;}' +
  'th,td{border:1px solid #444;padding:6px 10px;text-align:left;font-size:14px;}' +
  'th{background:#2a2a2a;} .badge{background:#333;padding:2px 8px;border-radius:4px;}' +
  'form.import-form{background:#232323;padding:16px;border-radius:8px;margin-bottom:24px;max-width:700px;}' +
  'label{display:block;margin-top:10px;font-size:13px;color:#aaa;}' +
  'input[type=text],input[type=date],select{width:100%;padding:6px;background:#1a1a1a;color:#e0e0e0;border:1px solid #444;border-radius:4px;}' +
  'button{margin-top:12px;padding:8px 16px;background:#2d6cdf;color:#fff;border:none;border-radius:4px;cursor:pointer;}' +
  '.hint{font-size:12px;color:#888;margin-top:4px;}' +
  '</style></head><body>' +
  (__navHtml || '<div style="background:#232323;border:1px solid #444;border-radius:6px;padding:8px 14px;margin-bottom:20px;display:flex;flex-wrap:wrap;gap:4px 16px;font-size:13px;"><a href="/webhook/aktien-status" style="color:#8ab4f8;text-decoration:none;">Status</a><a href="/webhook/aktien-watchlist" style="color:#8ab4f8;text-decoration:none;">Watchlist</a><a href="/webhook/rss-quellen" style="color:#8ab4f8;text-decoration:none;">RSS-Quellen</a><a href="/webhook/lernvorschlaege" style="color:#8ab4f8;text-decoration:none;">Lernvorschlaege</a><a href="/webhook/historische-marktdaten" style="color:#8ab4f8;text-decoration:none;">Marktdaten-Import</a><a href="/webhook/historische-nachrichten" style="color:#8ab4f8;text-decoration:none;">Nachrichten-Import</a><a href="/webhook/historische-news-lernkandidaten" style="color:#8ab4f8;text-decoration:none;">News-Lernkandidaten</a><a href="/webhook/historische-news-ausschluesse" style="color:#8ab4f8;text-decoration:none;">Ausschlussregeln</a><a href="/webhook/historische-simulation" style="color:#8ab4f8;text-decoration:none;">Simulationslaeufe</a><a href="/webhook/simulation-lauf" style="color:#8ab4f8;text-decoration:none;">Simulation starten</a><a href="/webhook/simulation-uebersicht" style="color:#8ab4f8;text-decoration:none;">Sim-Uebersicht</a><a href="/webhook/simulation-vergleich" style="color:#8ab4f8;text-decoration:none;">Sim-Vergleich</a></div>') +
  '<h1>Historische Marktdaten importieren</h1>' +
  '<form class="import-form" method="post" action="/webhook/historische-marktdaten">' +
    '<input type="hidden" name="action" value="create_import">' +
    '<label>Instrumente (Komma-getrennt)</label>' +
    '<input type="text" name="instruments" value="' + esc(prefillInstruments) + '" required>' +
    '<div class="hint">Vorbelegt mit der aktuellen Watchlist - kann frei geaendert/erweitert werden (auch Instrumente ausserhalb der Watchlist).</div>' +
    '<label>Zeitraum</label>' +
    '<select name="period_mode">' +
      '<option value="period">Vordefinierte Periode</option>' +
      '<option value="range">Fester Zeitraum (Start/Ende)</option>' +
    '</select>' +
    '<label>Periode (falls oben gewaehlt)</label>' +
    '<select name="period">' +
      '<option value="5y">5 Jahre</option>' +
      '<option value="10y">10 Jahre</option>' +
      '<option value="max">Maximal verfuegbare Historie</option>' +
    '</select>' +
    '<label>Startdatum (falls "Fester Zeitraum" gewaehlt)</label>' +
    '<input type="date" name="period_from">' +
    '<label>Enddatum (falls "Fester Zeitraum" gewaehlt)</label>' +
    '<input type="date" name="period_to">' +
    '<label>Umgang mit bereits vorhandenen Daten</label>' +
    '<select name="overwrite_mode">' +
      '<option value="fill_gaps">Nur Luecken ergaenzen</option>' +
      '<option value="skip_existing">Vorhandene ueberspringen</option>' +
      '<option value="overwrite">Vorhandene ueberschreiben</option>' +
    '</select>' +
    '<label><input type="checkbox" name="dry_run" value="true" style="width:auto;display:inline;"> Testlauf (prueft nur, schreibt keine Daten)</label>' +
    '<div class="hint">Ein Testlauf prueft Instrumente und Erreichbarkeit des Datenanbieters, schreibt aber keine historischen Daten.</div>' +
    '<button type="submit">Import starten</button>' +
  '</form>' +
  '<h2>Bisherige Importe</h2>' +
  '<table><tr><th>Job-ID</th><th>Anbieter</th><th>Instrumente</th><th>Zeitraum</th><th>Status</th><th>Fortschritt</th><th>Letzter Heartbeat</th><th>Aktionen</th></tr>' +
  jobsHtml +
  '</table>' +
  '</body></html>';

return [{ json: { html } }];

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgBool(v) { return v === null || v === undefined ? 'NULL' : (v ? 'TRUE' : 'FALSE'); }
function pgJsonb(v) { return (v === null || v === undefined) ? "'{}'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }
function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Berlin',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(date);
}

// REPARATUR-Auftrag Historische Simulation, Workflow 15: Aktions-Whitelist-Pattern,
// identisch zu "Watchlist verwalten"/"RSS-Quellen verwalten" - EIN Code-Node baut das
// komplette SQL als BEGIN/COMMIT-Block, EIN generischer Postgres-Node fuehrt es aus.
// Kein Aktions-Feld aus dem Formular wird ungeprueft in SQL interpoliert - Whitelist +
// pgStr/pgNum/pgJsonb fuer jeden Wert.

const ALLOWED_ACTIONS = new Set(['create_import', 'pause', 'resume', 'cancel', 'retry_failed']);
const ALLOWED_PROVIDERS = new Set(['yfinance']);
const ALLOWED_OVERWRITE_MODES = new Set(['fill_gaps', 'overwrite', 'skip_existing']);
// Gleiche Regel wie TICKER_REGEX im FastAPI-Kursdienst (app.py) - Verteidigung in der Tiefe,
// nicht nur serverseitige Validierung im Kursdienst selbst vertrauen.
const TICKER_REGEX = /^[A-Za-z0-9.\-^=]{1,20}$/;

const body = $input.item.json.body || $input.item.json;
const action = String(body.action || '').trim();

if (!ALLOWED_ACTIONS.has(action)) {
  return { json: { _error: 'Unbekannte Aktion: ' + action, sql: null } };
}

function randHex(n) {
  let s = '';
  for (let i = 0; i < n; i++) s += Math.floor(Math.random() * 16).toString(16);
  return s;
}

let sql = '';
let responseInfo = { action };

if (action === 'create_import') {
  const rawInstruments = String(body.instruments || '').split(',').map(s => s.trim()).filter(Boolean);
  const seen = new Set();
  const instruments = [];
  const invalidInstruments = [];
  for (const raw of rawInstruments) {
    const t = raw.toUpperCase();
    if (!TICKER_REGEX.test(t)) { invalidInstruments.push(raw); continue; }
    if (seen.has(t)) continue;
    seen.add(t);
    instruments.push(t);
  }

  const provider = ALLOWED_PROVIDERS.has(body.provider) ? body.provider : 'yfinance';
  const overwriteMode = ALLOWED_OVERWRITE_MODES.has(body.overwrite_mode) ? body.overwrite_mode : 'fill_gaps';
  const dryRun = body.dry_run === 'true' || body.dry_run === true;
  const periodMode = body.period_mode === 'range' ? 'range' : 'period';

  let periodFrom = null, periodTo = null, periodParam = null;
  if (periodMode === 'range') {
    periodFrom = body.period_from || null;
    periodTo = body.period_to || null;
  } else {
    const ALLOWED_PERIODS = new Set(['1d','5d','1mo','3mo','6mo','1y','2y','5y','10y','ytd','max']);
    periodParam = ALLOWED_PERIODS.has(body.period) ? body.period : '5y';
  }

  if (instruments.length === 0) {
    return { json: { _error: 'Keine gueltigen Instrumente angegeben.' + (invalidInstruments.length ? ' Ungueltig: ' + invalidInstruments.join(', ') : ''), sql: null } };
  }

  const jobId = 'imp-' + getBusinessDate() + '-' + randHex(6);
  const parametersJson = { period: periodParam };

  const jobInsert = `INSERT INTO trading.import_jobs
    (job_id, job_type, status, provider, instrument_selection_json, period_from, period_to, dry_run, overwrite_mode, parameters_json, progress_total)
    VALUES (${pgStr(jobId)}, 'market_data', 'queued', ${pgStr(provider)}, ${pgJsonb(instruments)},
            ${pgStr(periodFrom)}, ${pgStr(periodTo)}, ${pgBool(dryRun)}, ${pgStr(overwriteMode)},
            ${pgJsonb(parametersJson)}, ${pgNum(instruments.length)});`;

  const itemValues = instruments.map((ticker, idx) =>
    `(${pgStr(jobId)}, ${pgNum(idx + 1)}, ${pgStr(ticker)}, ${pgStr(periodFrom)}, ${pgStr(periodTo)}, 'pending')`
  ).join(',\n    ');

  const itemsInsert = `INSERT INTO trading.import_job_items
    (job_id, sequence_number, instrument, period_from, period_to, status)
    VALUES\n    ${itemValues};`;

  sql = `${jobInsert}\n${itemsInsert}`;
  responseInfo = { action, job_id: jobId, instrument_count: instruments.length, invalid_instruments: invalidInstruments, dry_run: dryRun };

} else if (action === 'pause') {
  const jobId = String(body.job_id || '').trim();
  if (!jobId) return { json: { _error: 'job_id fehlt.', sql: null } };
  sql = `UPDATE trading.import_jobs SET status = 'pausing' WHERE job_id = ${pgStr(jobId)} AND status IN ('queued','running');`;
  responseInfo = { action, job_id: jobId };

} else if (action === 'resume') {
  const jobId = String(body.job_id || '').trim();
  if (!jobId) return { json: { _error: 'job_id fehlt.', sql: null } };
  sql = `UPDATE trading.import_jobs SET status = 'queued' WHERE job_id = ${pgStr(jobId)} AND status = 'paused';`;
  responseInfo = { action, job_id: jobId };

} else if (action === 'cancel') {
  const jobId = String(body.job_id || '').trim();
  if (!jobId) return { json: { _error: 'job_id fehlt.', sql: null } };
  sql = `UPDATE trading.import_jobs SET status = 'cancelled', finished_at = now() WHERE job_id = ${pgStr(jobId)} AND status IN ('draft','queued','running','pausing','paused');
UPDATE trading.import_job_items SET status = 'skipped' WHERE job_id = ${pgStr(jobId)} AND status IN ('pending','running');`;
  responseInfo = { action, job_id: jobId };

} else if (action === 'retry_failed') {
  const jobId = String(body.job_id || '').trim();
  if (!jobId) return { json: { _error: 'job_id fehlt.', sql: null } };
  sql = `UPDATE trading.import_job_items SET status = 'pending', error = NULL WHERE job_id = ${pgStr(jobId)} AND status = 'failed';
UPDATE trading.import_jobs SET status = 'queued' WHERE job_id = ${pgStr(jobId)} AND status IN ('completed_with_warnings','failed');`;
  responseInfo = { action, job_id: jobId };
}

return { json: { sql, ...responseInfo } };

// Baut die JSON-Antwort fuer die POST-Aktion. "POST: SQL ausfuehren" (Postgres-Node ohne
// RETURNING) ersetzt das Item-JSON durch sein eigenes Ergebnis ({success:true} bzw. ein
// Fehlerobjekt) - dieselbe "Write-Node-ueberschreibt-Item"-Bugklasse wie an mehreren Stellen
// im Projekt bereits dokumentiert (siehe z.B. Workflow 10s Pruef-Agent-Fix). Die eigentlichen
// Antwortfelder (action/job_id/...) deshalb explizit vom SQL-Bauen-Node zurueckholen, nicht
// aus dem aktuellen $json.
const original = $('POST: Formular normalisieren + SQL bauen').item.json;
const current = $json;

if (original._error) {
  return { json: { ok: false, error: original._error } };
}
if (current.error) {
  return { json: { ok: false, error: 'Datenbankfehler beim Ausfuehren der Aktion.', action: original.action, job_id: original.job_id } };
}
return { json: { ok: true, action: original.action, job_id: original.job_id, instrument_count: original.instrument_count, invalid_instruments: original.invalid_instruments, dry_run: original.dry_run } };

// Kein aktiver Job -> Lauf beenden. Job pausierend -> auf 'paused' setzen und beenden
// (das laufende Paket, falls eines lief, wurde im vorherigen Worker-Lauf bereits sauber
// abgeschlossen, bevor 'pausing' gesetzt wurde - siehe Kommentar am Ende der Item-Schleife).
// alwaysOutputData:true auf "DB: Naechsten aktiven Job finden" liefert bei 0 aktiven Jobs ein
// Platzhalter-Item ohne job_id (statt dass n8n diesen Node gar nicht erst ausfuehrt) - anhand
// des Pflichtfelds job_id von einem echten Treffer unterscheiden.
const items = $input.all().filter(i => i.json && i.json.job_id);
if (items.length === 0) {
  return [{ json: { _kein_job: true } }];
}
const job = items[0].json;
return [{ json: { ...job, _kein_job: false, _job_pausierend: job.status === 'pausing' } }];

// Traegt Job-Daten und Konfigurationswerte zusammen, bevor das naechste Paket geladen wird.
const job = $('Pruefe Job-Zustand').all()[0].json;
const cfgRows = $input.all().map(i => i.json);
const cfgByKey = {};
for (const r of cfgRows) cfgByKey[r.config_key] = Number(r.value_numeric);
const packageSize = cfgByKey.IMPORT_DEFAULT_PACKAGE_SIZE || 1;
const maxRetries = cfgByKey.IMPORT_MAX_RETRY_ATTEMPTS || 3;
return [{ json: { ...job, _package_size: packageSize, _max_retries: maxRetries } }];

// Kein offenes Item mehr -> Job abschliessen (completed/completed_with_warnings, je nachdem
// ob Fehler aufgetreten sind). Sonst: Paket zur Verarbeitung weiterreichen.
// alwaysOutputData:true auf "DB: Naechstes Paket laden" liefert bei 0 offenen Items ein
// Platzhalter-Item ohne id - anhand des Pflichtfelds id von einem echten Item unterscheiden,
// sonst wuerde "IF: Paket leer" die Job-Fertigstellung nie erkennen.
const job = $('Baue Paket-Kontext').all()[0].json;
const items = $input.all().map(i => i.json).filter(j => j && j.id !== undefined && j.id !== null);
function parseJsonField(v, fallback) {
  if (v === null || v === undefined) return fallback;
  if (typeof v === 'object') return v;
  try { return JSON.parse(v); } catch (e) { return fallback; }
}
const paramsObj = parseJsonField(job.parameters_json, {});
if (items.length === 0) {
  // Muss trotzdem mindestens 1 Item zurueckgeben, sonst wuerde n8n den nachfolgenden
  // "IF: Paket leer"-Node bei 0 Items gar nicht erst ausfuehren (gleiches Prinzip wie
  // alwaysOutputData bei DB-Nodes) - "IF: Paket leer" erkennt dieses Platzhalter-Item am
  // fehlenden id-Feld, nicht an der reinen Itemanzahl.
  return [{ json: { _placeholder: true, job_id: job.job_id } }];
}
return items.map(it => ({ json: { ...it, _job_id: job.job_id, _max_retries: job._max_retries, _provider: job.provider, _period_param: paramsObj.period || null, _overwrite_mode: job.overwrite_mode, _dry_run: job.dry_run === true } }));

// Baut die URL fuer den historischen Kursabruf - entweder ueber "period" (5y/10y/max) oder
// einen expliziten Start-/End-Bereich, je nachdem was beim Import-Start gewaehlt wurde.
// "DB: Item auf running setzen" (Postgres-UPDATE ohne RETURNING) ersetzt das Item-JSON durch
// sein eigenes {success:true}-Ergebnis - die eigentlichen Item-Felder deshalb vom Node VOR dem
// UPDATE zurueckholen (gleiche Bugklasse wie beim POST-Antwort-Node, siehe dortiger Kommentar).
const it = $('Loop: Instrumente verarbeiten').item.json;
// period_from/period_to kommen aus einer DATE-Spalte, die von Postgres/node-postgres als
// voller ISO-Zeitstempel zurueckgegeben wird (z.B. '2026-06-01T00:00:00.000Z') - der
// FastAPI-Kursdienst verlangt aber strikt YYYY-MM-DD (siehe app.py parse_date()), sonst
// INVALID_PARAMETERS. Auf reines Datum kuerzen, bevor die URL gebaut wird.
function toDateOnly(v) {
  if (!v) return v;
  return String(v).slice(0, 10);
}
const periodFrom = toDateOnly(it.period_from);
const periodTo = toDateOnly(it.period_to);
const base = 'http://172.16.1.14:8099';
const ticker = encodeURIComponent(it.instrument);
let url;
if (it._period_param) {
  url = base + '/api/v1/history/' + ticker + '?period=' + encodeURIComponent(it._period_param);
} else {
  url = base + '/api/v1/history/' + ticker + '?start=' + encodeURIComponent(periodFrom) + '&end=' + encodeURIComponent(periodTo);
}
return { json: { ...it, _history_url: url, _actions_url: base + '/api/v1/actions/' + ticker + (it._period_param ? '' : ('?start=' + encodeURIComponent(periodFrom) + '&end=' + encodeURIComponent(periodTo))) } };

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgBool(v) { return v === null || v === undefined ? 'NULL' : (v ? 'TRUE' : 'FALSE'); }
function pgJsonb(v) { return (v === null || v === undefined) ? "'{}'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }

// Wertet beide HTTP-Antworten aus (Kurse + Corporate Actions), baut die Insert-SQL-Statements
// (Duplikatschutz ueber ON CONFLICT gemaess overwrite_mode) und die Item-Abschluss-Aktualisierung.
// Ein fehlgeschlagener Kursabruf laesst das Item bei attempt < max_retries auf 'pending'
// zurueckfallen (automatischer Retry beim naechsten Worker-Lauf), sonst 'failed'. Ein
// fehlgeschlagener Corporate-Actions-Abruf blockiert die Kursdaten NICHT - Kurse sind der
// primaere Zweck dieses Imports, Corporate Actions eine Ergaenzung (weiche Abhaengigkeit).

// $('Node').item ist paired-item-abhaengig und bricht in dieser Kette (2 sequentielle
// HTTP-Nodes mit onError:continueRegularOutput) nachweislich - live am 2026-08-04 gefunden:
// fehlgeschlagene Abrufe schrieben ihr Ergebnis auf FALSCHE import_job_items-Zeilen (sogar
// eines ANDEREN Jobs/job_type, da die id-Spalte global ueber die Tabelle laeuft). SplitInBatches
// mit batchSize=1 garantiert genau 1 Item pro Lauf, .all()[0] ist deshalb sicher und eindeutig.
const it = $('Baue Abruf-URLs').all()[0].json;
// Direkter Input dieses Nodes ist "HTTP: Corporate Actions abrufen" (letzter Schritt der
// Kette), NICHT "HTTP: Kurse abrufen" - beide Antworten deshalb explizit ueber ihren
// jeweiligen Node-Namen lesen statt $input/$json zu verwenden.
const kurse = $('HTTP: Kurse abrufen').all()[0].json;

const jobId = it._job_id;
const itemId = it.id;
const ticker = it.instrument;
const provider = it._provider;
const overwriteMode = it._overwrite_mode;
const dryRun = it._dry_run === true;
const maxRetries = Number(it._max_retries || 3);
// 'it.attempt' ist der Stand VOR dem Increment in "DB: Item auf running setzen" (dieser
// Code-Node liest das urspruenglich geladene Item, nicht das Ergebnis des UPDATEs) - der
// tatsaechliche, gerade eben in der DB gesetzte Versuchszaehler ist deshalb +1 hoeher.
const attempt = Number(it.attempt || 0) + 1;

const kurseOk = kurse && kurse.success === true && kurse.data && Array.isArray(kurse.data.rows);

if (!kurseOk) {
  const errMsg = (kurse && kurse.error && kurse.error.message) ? kurse.error.message : 'Unbekannter Fehler beim Kursabruf.';
  const willRetry = attempt < maxRetries;
  const newStatus = willRetry ? 'pending' : 'failed';
  const sql = `UPDATE trading.import_job_items SET status = ${pgStr(newStatus)}, finished_at = ${willRetry ? 'NULL' : 'now()'}, error = ${pgStr(errMsg)} WHERE id = ${pgNum(itemId)};`;
  return { json: { sql, _job_id: jobId, _failed: true } };
}

const rows = kurse.data.rows;
const fetchedAt = new Date().toISOString();

let priceInsert = '';
if (!dryRun && rows.length > 0) {
  const conflictClause = overwriteMode === 'overwrite'
    ? `DO UPDATE SET open = EXCLUDED.open, high = EXCLUDED.high, low = EXCLUDED.low, close = EXCLUDED.close, adjusted_close = EXCLUDED.adjusted_close, volume = EXCLUDED.volume, fetched_at = EXCLUDED.fetched_at`
    : `DO NOTHING`;
  const values = rows.map(r => `(${pgStr(ticker)}, ${pgStr(r.date)}, ${pgNum(r.open)}, ${pgNum(r.high)}, ${pgNum(r.low)}, ${pgNum(r.close)}, ${pgNum(r.adjusted_close)}, ${pgNum(r.volume)}, ${pgStr(kurse.data.currency)}, ${pgStr(kurse.data.exchange)}, ${pgStr(provider)}, ${pgStr(jobId)}, ${pgStr(fetchedAt)})`).join(',\n    ');
  priceInsert = `INSERT INTO trading.historical_price_data
    (ticker, trading_date, open, high, low, close, adjusted_close, volume, currency, exchange, provider, import_job_id, fetched_at)
    VALUES\n    ${values}
    ON CONFLICT (ticker, trading_date, provider) ${conflictClause};`;
}

const actions = $('HTTP: Corporate Actions abrufen').all()[0].json;
const actionsOk = actions && actions.success === true && actions.data && Array.isArray(actions.data.rows);
let actionsInsert = '';
if (!dryRun && actionsOk && actions.data.rows.length > 0) {
  const actionRows = actions.data.rows.filter(r => r.type === 'dividend' || r.type === 'split');
  if (actionRows.length > 0) {
    const values = actionRows.map(r => {
      const isDividend = r.type === 'dividend';
      return `(${pgStr(ticker)}, ${pgStr(r.type)}, ${pgStr(r.date)}, ${isDividend ? 'NULL' : pgNum(r.value)}, ${isDividend ? pgNum(r.value) : 'NULL'}, ${pgStr(kurse.data.currency)}, ${pgStr(r.source || provider)}, ${pgStr(jobId)})`;
    }).join(',\n    ');
    actionsInsert = `INSERT INTO trading.historical_corporate_actions
      (ticker, action_type, ex_date, split_ratio, dividend_amount, currency, source, import_job_id)
      VALUES\n    ${values}
      ON CONFLICT (ticker, action_type, ex_date, source) DO NOTHING;`;
  }
}

const checkpoint = { row_count: rows.length, actual_start: kurse.data.actual_start, actual_end: kurse.data.actual_end, dry_run: dryRun };
const itemUpdate = `UPDATE trading.import_job_items SET status = 'completed', finished_at = now(), checkpoint_json = ${pgJsonb(checkpoint)}, error = NULL WHERE id = ${pgNum(itemId)};`;

const sql = `${priceInsert}
${actionsInsert}
${itemUpdate}`;

return { json: { sql, _job_id: jobId, _failed: false, _row_count: rows.length } };
